func Run(ctx context.Context, d Dependencies, r Request) (Result, error) {
	if d == nil || r.ManagedKey == "" || r.Port < 1 || r.Port > 65535 {
		return Result{}, ErrDependency
	}

ready, err := d.Ready(ctx)
if err != nil {
	return Result{}, err
}
if !ready {
	return Result{}, ErrNotReady
}
before, err := d.RefreshInventory(ctx)

if err != nil {
	return Result{}, err
}
if existing, ok := findManaged(before, r.ManagedKey); ok {
	payload, err := d.Build(ctx, r)
	if err != nil {
		return Result{}, err
	}

	if existing.RemoteID <= 0 {
		return Result{}, ErrUnconfirmed
	}
	if err := d.Verify(ctx, existing.RemoteID, payload); err != nil {
		return Result{}, err
	}
	return Result{Noop: true, Confirmed: true}, nil
}

for _, x := range before {
	if x.Port == r.Port {
		return Result{}, ErrPortOccupied
	}
}
ports, err := d.OccupiedPorts(ctx)
if err != nil {
	return Result{}, err

}
for _, p := range ports {
	if p == r.Port {
		return Result{}, ErrPortOccupied
	}
}
payload, err := d.Build(ctx, r)
if err != nil {

	return Result{}, err
}
addErr := d.Add(ctx, payload)
after, invErr := d.RefreshInventory(ctx)
if invErr != nil {
	if addErr != nil {
		return Result{}, addErr
	}

	return Result{}, ErrUnconfirmed
}
if created, ok := findManaged(after, r.ManagedKey); ok {
	if created.RemoteID <= 0 {
		return Result{}, ErrUnconfirmed
	}
	if err := d.Verify(ctx, created.RemoteID, payload); err != nil {
		return Result{}, err

		}
		return Result{Created: true, Confirmed: true}, nil
	}
	if addErr != nil {
		return Result{}, addErr
	}
	return Result{}, ErrUnconfirmed
}

func contains(xs []inventory.InboundRecord, key string) bool {
	for _, x := range xs {
		if x.Remark == key {
			return true
		}
	}
	return false

}

func findManaged(xs []inventory.InboundRecord, key string) (inventory.InboundRecord, bool) {
	var found inventory.InboundRecord
	count := 0
	for _, x := range xs {
		if x.Remark == key {
			found = x

			count++
		}
	}
	return found, count == 1
}

}

